 let pts = [];
 if (ap.hijab === "shawl") { const sd = (hash([ap.skin, ap.hijabColor, ap.face].join("")) >> 3) % 2 ? 1 : -1, P = v => 100 + sd * v; for (let i = 0; i <= 16; i++) { const t = i / 16; pts.push(t < .5 ? bez([P(-jw - 6), cy + 20], [P(-jw - 4), cy + 30], [P(-jw * .4), cy + 38], [P(jw * .3), cy + 38], t * 2) : bez([P(jw * .3), cy + 38], [P(jw * .75), cy + 35], [P(jw + 10), cy + 26], [P(jw + 16), cy + 16], (t - .5) * 2)) } }
