(function(){
/* ===== v67: fewer pop-ups at once (owner: "Keluar multiple popup and status — rimas")
   The game stacks up to three notices at the bottom (and again at the top while a panel is open), and on opening a
   save it fires a burst of world news. Every notice still happens and is still written to the Diari / Warta / Ringkasan
   as before; only what shows on screen changes:
   - one notice at a time: a new one replaces the one showing;
   - the same notice again within a minute is not shown twice;
   - the burst of news in the first 12 seconds after the game opens is not shown (it is in the Diari).
   RKQuiet.on = false brings the old stacking back. ===== */
const QT = window.RKQuiet = { on: true, err: 0, lastErr: "", boot: Date.now(), seen: new Map, hidden: 0 };
const fail = e => { QT.err++; QT.lastErr = String(e && e.stack || e).slice(0, 400) };
function tidy(box) {
 if (!QT.on || !box) return;
 try {
  const now = Date.now(), kids = [...box.children];
  if (!kids.length) return;
  const newest = box.id === "toasts" ? kids[0] : kids[kids.length - 1];
  for (const el of kids) {
   if (el === newest) continue;
   el.remove(); QT.hidden++
  }
  if (!newest || newest._qt) return;
  newest._qt = 1;
  const key = (newest.textContent || "").trim();
  const seen = QT.seen.get(key);
  if (now - QT.boot < 12000 || seen != null && now - seen < 60000) { newest.remove(); QT.hidden++ }
  QT.seen.set(key, now);
  if (QT.seen.size > 200) for (const [k, t] of QT.seen) if (now - t > 60000) QT.seen.delete(k)
 } catch (e) { fail(e) }
}
function watch(box) {
 if (!box || box._qtw) return;
 box._qtw = 1;
 try { new MutationObserver(() => tidy(box)).observe(box, { childList: true }) } catch (e) { fail(e) }
 tidy(box)
}
function hook() {
 try {
  watch(document.getElementById("toasts"));
  const top = document.getElementById("toasttop");
  if (top) watch(top)
 } catch (e) { fail(e) }
}
hook();
try { new MutationObserver(() => { if (!document.getElementById("toasttop")?._qtw || !document.getElementById("toasts")?._qtw) hook() }).observe(document.body, { childList: true }) } catch (e) { fail(e) }

})();
