   zc.insertAdjacentHTML("afterbegin", `<button class="hfb hff" type="button" aria-label="Kamera ikut watak" title="Kamera ikut watak (F)">🎯</button><button class="hfb hfw" type="button" aria-label="Dinding" title="Tukar dinding (C)">🧱</button>`);
   zc.querySelector(".hff").addEventListener("click", e => { e.stopPropagation(); if (zNow() <= 1 && !HF.follow) zoomTo(1.8); setFollow(!HF.follow) });
   zc.querySelector(".hfw").addEventListener("click", e => { e.stopPropagation(); cycleWalls() })
