 /* ---------- 4. Moodlets: every part of the mood number, with its reason and time left ---------- */
 const fmtLeft = m => m >= 1440 ? Math.round(m / 1440) + " hari" : m >= 60 ? Math.round(m / 60) + " jam" : Math.max(1, Math.round(m)) + " min";
